        private readonly Func<IReadOnlyCollection<IElementDefinitionSummary>> _elementsFactory;
        private IReadOnlyCollection<IElementDefinitionSummary>? _elements;

        public GeneratedStructureDefinitionSummary(
            string typeName,
            bool isAbstract,
            bool isResource,
            Func<IReadOnlyCollection<IElementDefinitionSummary>> elementsFactory)
        {
            TypeName = typeName;
            IsAbstract = isAbstract;
            IsResource = isResource;
            _elementsFactory = elementsFactory;
        }

        public string TypeName { get; }
        public bool IsAbstract { get; }
        public bool IsResource { get; }

        // IStructureDefinitionReference implementation
        // ReferredType returns the type name for choice type validation
        public string ReferredType => TypeName;

        public IReadOnlyCollection<IElementDefinitionSummary> GetElements()
        {
            return _elements ??= _elementsFactory();
        }
    }

    /// <summary>
    /// Extended element definition summary with additional metadata beyond IElementDefinitionSummary.
    /// </summary>
    private sealed class GeneratedElementDefinitionSummary : IElementDefinitionSummary, IExtendedElementMetadata
    {
        public GeneratedElementDefinitionSummary(
            string elementName,
            bool isCollection,
            bool isRequired,
            bool inSummary,
            bool isChoiceElement,
            bool isResource,
            bool isModifier,
            ITypeSerializationInfo[] type,
            string defaultTypeName,
            string? nonDefaultNamespace,
            XmlRepresentation representation,
            int order,
            string[]? referenceTargets = null,
            BindingMetadata? binding = null,
            ConstraintMetadata[]? constraints = null,
            SlicingMetadata? slicing = null,
            string? fixedValue = null,
            string? patternValue = null,
            string? defaultValue = null,
            string? contentReference = null,
            int? min = null,
            string? max = null)
        {
            ElementName = elementName;
            IsCollection = isCollection;
            IsRequired = isRequired;
            InSummary = inSummary;
            IsChoiceElement = isChoiceElement;
            IsResource = isResource;
            IsModifier = isModifier;
            Type = type;
            DefaultTypeName = defaultTypeName;
            NonDefaultNamespace = nonDefaultNamespace;
            Representation = representation;
            Order = order;
            ReferenceTargets = referenceTargets;
            Binding = binding;
            Constraints = constraints;
            Slicing = slicing;
            FixedValue = fixedValue;
            PatternValue = patternValue;
            DefaultValue = defaultValue;
            ContentReference = contentReference;
            Min = min;
            Max = max;
        }

        // IElementDefinitionSummary properties
        public string ElementName { get; }
        public bool IsCollection { get; }
        public bool IsRequired { get; }
        public bool InSummary { get; }
        public bool IsChoiceElement { get; }
        public bool IsResource { get; }
        public bool IsModifier { get; }
        public ITypeSerializationInfo[] Type { get; }
        public string DefaultTypeName { get; }
        public string? NonDefaultNamespace { get; }
        public XmlRepresentation Representation { get; }
        public int Order { get; }

        // Extended metadata properties (IExtendedElementMetadata)
        /// <summary>Valid target resource types for Reference elements.</summary>
        public string[]? ReferenceTargets { get; }

        /// <summary>ValueSet binding information.</summary>
        public BindingMetadata? Binding { get; }

        /// <summary>FHIRPath constraints (invariants).</summary>
        public ConstraintMetadata[]? Constraints { get; }

        /// <summary>Slicing definition.</summary>
        public SlicingMetadata? Slicing { get; }

        /// <summary>Fixed value (serialized as JSON string).</summary>
        public string? FixedValue { get; }

        /// <summary>Pattern value (serialized as JSON string).</summary>
        public string? PatternValue { get; }

        /// <summary>Default value (serialized as JSON string).</summary>
        public string? DefaultValue { get; }

        /// <summary>Content reference (e.g., "#Patient.contact" for recursive structures).</summary>
        public string? ContentReference { get; }

        /// <summary>Minimum cardinality.</summary>
        public int? Min { get; }

        /// <summary>Maximum cardinality ("*" for unbounded).</summary>
        public string? Max { get; }
    }
}
